import React from 'react';
import { TrackKit } from './index';

const previews = {
  componentName: 'TrackKit',
  importPath: 'components/TrackKit',
  previews: [
    { name: '3D rig', description: "Composable coaster track pieces (RCT2 TrackElemType-style) with spline rails, train-follow and clearance-aware wooden supports.", render: () => <TrackKit /> },
  ],
};

export default previews;

import React from 'react';
import * as THREE from 'three';
import { Stage, box, cyl, mat } from '../Stage';

// ---------------------------------------------------------------------------
// TrackKit — composable roller-coaster track, modelled on RCT2's track-piece
// system. RCT2 builds coasters from a fixed vocabulary of TrackElemTypes
// (flat, gentle 25° slopes, steep 60°, quarter turns, corkscrews...) and gives
// every element a CLEARANCE HEIGHT (RideData ClearanceHeight — the vertical
// envelope a train sweeps through). Wooden-coaster supports must never enter
// that envelope, so when structure would cross a lower track, it is split
// around [railY - STRUCT_DEPTH, railY + CLEARANCE]. We reproduce both ideas:
// a piece vocabulary compiled into a smooth closed spline, and support bents
// that check every other track pass before building through it.
// ---------------------------------------------------------------------------

export type PieceName =
  | 'station'
  | 'flat'
  | 'up25'
  | 'down25'
  | 'up60'
  | 'down60'
  | 'turnL'
  | 'turnR'
  | 'corkscrewL'
  | 'corkscrewR';

const STEP = 1.3; // horizontal run of one straight piece (one "tile")
const RISE25 = 0.55; // rise of a gentle slope piece (RCT2 gentle = 25°)
const RISE60 = 1.15; // rise of a steep piece
const TURN_R = 1.5; // quarter-turn radius
export const CLEARANCE = 0.85; // RCT2-style clearance envelope above the rail
const STRUCT_DEPTH = 0.3; // structure depth below the rail

interface CompiledTrack {
  curve: THREE.CatmullRomCurve3;
  rollOf: (u: number) => number;
  stations: THREE.Vector3[];
}

/** Compile a piece list into a smooth closed spline + roll profile. */
export function compileTrack(t: typeof THREE, pieces: PieceName[]): CompiledTrack {
  const pts: THREE.Vector3[] = [];
  const rolls: { i: number; roll: number }[] = [];
  const stations: THREE.Vector3[] = [];
  const pos = new t.Vector3(0, 1.0, 0);
  let yaw = 0;
  let roll = 0;
  const fwd = () => new t.Vector3(Math.sin(yaw), 0, Math.cos(yaw));
  const push = (p: THREE.Vector3) => {
    pts.push(p.clone());
    rolls.push({ i: pts.length - 1, roll });
  };
  push(pos);
  for (const piece of pieces) {
    if (piece === 'station' || piece === 'flat') {
      if (piece === 'station') stations.push(pos.clone());
      pos.addScaledVector(fwd(), STEP);
      push(pos);
    } else if (piece === 'up25' || piece === 'down25' || piece === 'up60' || piece === 'down60') {
      const rise = (piece.startsWith('up') ? 1 : -1) * (piece.endsWith('60') ? RISE60 : RISE25);
      pos.addScaledVector(fwd(), STEP);
      pos.y = Math.max(0.55, pos.y + rise);
      push(pos);
    } else if (piece === 'turnL' || piece === 'turnR') {
      const s = piece === 'turnL' ? 1 : -1;
      // quarter circle in 3 chords around the turn centre
      const centre = pos.clone().addScaledVector(new t.Vector3(Math.cos(yaw), 0, -Math.sin(yaw)), -s * TURN_R);
      for (let k = 1; k <= 3; k++) {
        const a = (s * (k / 3) * Math.PI) / 2;
        const rel = pos.clone().sub(centre);
        const rot = rel.clone().applyAxisAngle(new t.Vector3(0, 1, 0), a);
        push(centre.clone().add(rot));
      }
      yaw += (s * Math.PI) / 2;
      pos.copy(pts[pts.length - 1]);
    } else if (piece === 'corkscrewL' || piece === 'corkscrewR') {
      // RCT2 corkscrew: full 360° roll across the element with a rise-fall hump
      const s = piece === 'corkscrewL' ? 1 : -1;
      const side = new t.Vector3(Math.cos(yaw), 0, -Math.sin(yaw));
      for (let k = 1; k <= 4; k++) {
        const f = k / 4;
        const p = pos
          .clone()
          .addScaledVector(fwd(), STEP * 2 * f)
          .addScaledVector(side, s * 0.5 * Math.sin(f * Math.PI));
        p.y += 0.55 * Math.sin(f * Math.PI);
        roll += (s * Math.PI * 2) / 4;
        push(p);
      }
      pos.copy(pts[pts.length - 1]);
    }
  }
  const curve = new t.CatmullRomCurve3(pts, true, 'centripetal', 0.5);
  const n = pts.length;
  const rollOf = (u: number) => {
    const f = u * n;
    const i0 = Math.floor(f) % n;
    const i1 = (i0 + 1) % n;
    const fr = f - Math.floor(f);
    return rolls[i0].roll * (1 - fr) + (rolls[i1].roll + (i1 === 0 ? 0 : 0)) * fr;
  };
  return { curve, rollOf, stations };
}

/** Frame (pos, forward, up, side) at u along the track, including roll. */
export function frameAt(t: typeof THREE, tk: CompiledTrack, u: number) {
  const uu = ((u % 1) + 1) % 1;
  const p = tk.curve.getPointAt(uu);
  const fwd = tk.curve.getTangentAt(uu).normalize();
  let up = new t.Vector3(0, 1, 0);
  up = up.sub(fwd.clone().multiplyScalar(up.dot(fwd))).normalize(); // orthogonalise
  up.applyAxisAngle(fwd, tk.rollOf(uu));
  const side = new t.Vector3().crossVectors(up, fwd).normalize();
  return { p, fwd, up, side };
}

export interface TrackStyle {
  wood?: boolean;
  railColor?: number;
  supportEvery?: number;
}

/** Render rails/ties/supports along the compiled track with clearance checks. */
export function buildTrackMesh(t: typeof THREE, g: THREE.Group, tk: CompiledTrack, style: TrackStyle = {}) {
  const RAIL = style.railColor ?? 0x8b8f96;
  const WOOD = 0x7a5230;
  const WOOD_D = 0x5f3f24;
  const GAP = 0.34; // half rail gauge
  const SAMPLES = 260;

  // pre-sample frames for rails + clearance queries
  const frames = [] as { p: THREE.Vector3; side: THREE.Vector3; up: THREE.Vector3 }[];
  for (let i = 0; i <= SAMPLES; i++) frames.push(frameAt(t, tk, i / SAMPLES));

  // rails as tubes along offset point chains
  [-1, 1].forEach((s) => {
    const off = frames.map((f) => f.p.clone().addScaledVector(f.side, s * GAP));
    const railCurve = new t.CatmullRomCurve3(off, true);
    const tube = new t.Mesh(new t.TubeGeometry(railCurve, SAMPLES, 0.045, 8, true), mat(t, RAIL, { tex: 'metal', repeat: [1, 40], metal: 0.8, rough: 0.35 }));
    tube.castShadow = true;
    g.add(tube);
  });
  // wooden stringers under the rails
  if (style.wood) {
    [-1, 1].forEach((s) => {
      const off = frames.map((f) => f.p.clone().addScaledVector(f.side, s * GAP).addScaledVector(f.up, -0.12));
      const c = new t.CatmullRomCurve3(off, true);
      const tube = new t.Mesh(new t.TubeGeometry(c, SAMPLES, 0.06, 6, true), mat(t, WOOD, { tex: 'wood', repeat: [1, 30], rough: 0.9 }));
      tube.castShadow = true;
      g.add(tube);
    });
  }
  // ties every few samples
  for (let i = 0; i < SAMPLES; i += 3) {
    const f = frames[i];
    const tie = box(t, [GAP * 2 + 0.28, 0.055, 0.13], style.wood ? 0x6b4626 : 0x4a4e55, [0, 0, 0], { tex: style.wood ? 'wood' : 'metal', repeat: [3, 1], rough: 0.9 });
    tie.position.copy(f.p).addScaledVector(f.up, -0.06);
    const m = new t.Matrix4().makeBasis(f.side, f.up, new t.Vector3().crossVectors(f.side, f.up));
    tie.setRotationFromMatrix(m);
    g.add(tie);
  }

  // supports with RCT2-style clearance: a bent may not pass through the
  // clearance envelope [railY - STRUCT_DEPTH, railY + CLEARANCE] of any OTHER
  // track pass crossing its column.
  const every = style.supportEvery ?? 9;
  for (let i = 0; i < SAMPLES; i += every) {
    const f = frames[i];
    const topY = f.p.y - 0.14;
    if (topY < 0.25) continue;
    // collect blocked intervals from other passes over this column
    const blocked: [number, number][] = [];
    for (let j = 0; j < SAMPLES; j += 2) {
      if (Math.abs(j - i) < 14 && Math.abs(j - i) > SAMPLES - 14) continue;
      const q = frames[j].p;
      const dx = q.x - f.p.x;
      const dz = q.z - f.p.z;
      if (dx * dx + dz * dz < 0.45 * 0.45 && Math.abs(q.y - f.p.y) > 0.3) {
        blocked.push([q.y - STRUCT_DEPTH, q.y + CLEARANCE]);
      }
    }
    // build the column as segments that skip blocked intervals
    const segs: [number, number][] = [];
    let y0 = 0;
    const stops = blocked.filter(([a, b]) => b > 0 && a < topY).sort((a, b) => a[0] - b[0]);
    for (const [a, b] of stops) {
      if (a > y0 + 0.12) segs.push([y0, Math.min(a, topY)]);
      y0 = Math.max(y0, b);
    }
    if (topY > y0 + 0.12) segs.push([y0, topY]);
    for (const [a, b] of segs) {
      const h = b - a;
      if (style.wood) {
        [-0.42, 0.42].forEach((sx) => {
          const post = box(t, [0.11, h, 0.11], WOOD, [0, 0, 0], { tex: 'wood', repeat: [1, 4], rough: 0.9 });
          post.position.set(f.p.x + f.side.x * sx, a + h / 2, f.p.z + f.side.z * sx);
          g.add(post);
        });
        if (h > 0.5) {
          const ledger = box(t, [0.95, 0.09, 0.09], WOOD_D, [0, 0, 0], { tex: 'wood', repeat: [4, 1], rough: 0.9 });
          ledger.position.set(f.p.x, a + h - 0.2, f.p.z);
          const m = new t.Matrix4().makeBasis(f.side, new t.Vector3(0, 1, 0), new t.Vector3().crossVectors(f.side, new t.Vector3(0, 1, 0)));
          ledger.setRotationFromMatrix(m);
          g.add(ledger);
          const brace = box(t, [1.1, 0.06, 0.05], WOOD_D, [0, 0, 0], { tex: 'wood', repeat: [4, 1], rough: 0.9 });
          brace.position.set(f.p.x, a + h / 2, f.p.z);
          brace.setRotationFromMatrix(m);
          brace.rotateZ(0.8);
          g.add(brace);
        }
      } else {
        const post = cyl(t, 0.07, 0.09, h, 0x9aa0a8, [0, 0, 0], { tex: 'metal', metal: 0.6, rough: 0.4, seg: 10 });
        post.position.set(f.p.x, a + h / 2, f.p.z);
        g.add(post);
      }
    }
  }
  // station platform(s)
  tk.stations.forEach((sp) => {
    g.add(box(t, [1.6, 0.12, 1.6], 0x8a8f98, [sp.x, sp.y - 0.35, sp.z], { tex: 'concrete', repeat: [5, 5], rough: 0.9 }));
    g.add(box(t, [1.6, 0.5, 0.1], 0xb03030, [sp.x, sp.y + 0.4, sp.z - 0.8], { tex: 'plastic', repeat: [6, 1], rough: 0.5 }));
    g.add(box(t, [1.7, 0.08, 1.0], 0x7a5230, [sp.x, sp.y + 0.68, sp.z - 0.4], { tex: 'wood', repeat: [6, 3], rough: 0.85, rotX: 0.25 }));
  });
  return frames;
}

/** Attach a train of car groups to the track; returns an updater. */
export function attachTrain(t: typeof THREE, g: THREE.Group, tk: CompiledTrack, cars: THREE.Group[], opts: { speed?: number; spacing?: number; wheelOffset?: number } = {}) {
  const speed = opts.speed ?? 0.045;
  const spacing = opts.spacing ?? 0.028;
  const wheelOffset = opts.wheelOffset ?? 0.09;
  cars.forEach((c) => g.add(c));
  const m = new t.Matrix4();
  return (time: number) => {
    const head = time * speed;
    cars.forEach((c, i) => {
      const f = frameAt(t, tk, head - i * spacing);
      c.position.copy(f.p).addScaledVector(f.up, wheelOffset);
      m.makeBasis(f.side, f.up, f.fwd);
      c.setRotationFromMatrix(m);
    });
  };
}

/** Standalone preview of the kit: a wooden figure-8-ish circuit. */
export function TrackKit() {
  return (
    <Stage
      distance={11}
      targetY={1.2}
      build={(t, g) => {
        const tk = compileTrack(t, ['station', 'flat', 'up25', 'up25', 'up25', 'down25', 'down25', 'corkscrewR', 'flat', 'turnR', 'up25', 'down25', 'turnR', 'flat', 'flat', 'turnR', 'flat', 'turnR']);
        buildTrackMesh(t, g, tk, { wood: true });
        const cars = [0, 1, 2].map(() => box(t, [0.5, 0.3, 0.9], 0xe0601a, [0, 0, 0], { tex: 'plastic', rough: 0.4 }) as unknown as THREE.Group);
        const run = attachTrain(t, g, tk, cars);
        return (time) => run(time);
      }}
    />
  );
}

import React from 'react';
import { CoasterBuilder } from './index';

const previews = {
  componentName: 'CoasterBuilder',
  importPath: 'components/CoasterBuilder',
  previews: [
    { name: '3D rig', description: "A wooden coaster COMPOSED from TrackKit pieces: station, chain lift, drops, corkscrew and turns \u2014 the train follows the spline.", render: () => <CoasterBuilder /> },
  ],
};

export default previews;

import React from 'react';
import * as THREE from 'three';
import { Stage, box } from '../Stage';
import { compileTrack, buildTrackMesh, attachTrain, PieceName } from '../TrackKit';
import { buildCoasterCar } from '../CoasterCar';
import { tree } from '../Kit';

// A COMPOSED wooden coaster built from TrackKit pieces exactly the way RCT2
// chains TrackElemTypes: station → chain-lift up (3× gentle 25°) → first drop
// → corkscrew → hop → quarter turns to close the circuit. The peep-filled
// train follows the spline (position + banked orientation from the piece roll
// profile), and the wooden support bents apply RCT2-style CLEARANCE: where a
// column would pass through a lower track's swept envelope it is split so the
// cars never drive through structure.
export function CoasterBuilder() {
  return (
    <Stage
      distance={12}
      targetY={1.3}
      build={(t, g) => {
        const LAYOUT: PieceName[] = [
          'station',
          'flat',
          'up25',
          'up25',
          'up25', // chain lift
          'down25',
          'down60', // first drop
          'flat',
          'corkscrewR', // inversion
          'flat',
          'turnR',
          'up25',
          'down25', // hop on the return leg
          'turnR',
          'flat',
          'flat',
          'turnR',
          'flat',
          'turnR', // close the circuit
        ];
        const tk = compileTrack(t, LAYOUT);
        buildTrackMesh(t, g, tk, { wood: true, supportEvery: 8 });

        // three detailed cars (each carries two peeps with faces)
        const cars: THREE.Group[] = [];
        for (let i = 0; i < 3; i++) {
          const c = buildCoasterCar(t);
          c.scale.setScalar(0.78);
          cars.push(c);
        }
        const run = attachTrain(t, g, tk, cars, { speed: 0.05, spacing: 0.026, wheelOffset: 0.1 });

        // a little landscaping so the circuit reads as a ride, not a diagram
        const pine = tree(t, { shape: 'pine', scale: 0.9 });
        pine.position.set(-2.6, 0, 3.2);
        g.add(pine);
        const oak = tree(t, { shape: 'round', scale: 0.8 });
        oak.position.set(4.2, 0, -2.4);
        g.add(oak);
        g.add(box(t, [1.4, 0.5, 0.1], 0xb03030, [0.65, 0.25, -1.05], { tex: 'plastic', repeat: [5, 1], rough: 0.5 })); // entrance sign wall

        return (time) => run(time);
      }}
    />
  );
}

import React from 'react';
import { ObservationTower } from './index';

const previews = {
  componentName: 'ObservationTower',
  importPath: 'components/ObservationTower',
  previews: [
    { name: '3D rig', description: "Observation tower: blue window drum + orange/white pinwheel roof cabin rising a lattice mast (OBS1).", render: () => <ObservationTower /> },
  ],
};

export default previews;

import React from 'react';
import { Stage, box, cyl, ball } from '../Stage';
import { buildPeep, SHIRTS, SKIN_TONES } from '../Guest';

// Observation tower matched to the RCT2 OBS1 sprite: a round DEEP-BLUE cabin
// drum with a ring of windows under an ORANGE/WHITE pinwheel cone roof, riding
// up and down a pale lattice mast while slowly rotating for the view.
export function ObservationTower() {
  return (
    <Stage
      distance={9.5}
      targetY={2.6}
      build={(t, g) => {
        const H = 5.6;
        const BLUE = 0x1a2f8c; // cabin drum (sprite #002090)
        const ORANGE = 0xe8641c;
        const CREAM = 0xdad4c8;
        const LATTICE = 0xc9ccd2;
        g.add(cyl(t, 0.9, 1.0, 0.35, 0x8a8f98, [0, 0.17, 0], { tex: 'concrete', repeat: [8, 1], rough: 0.9, seg: 28 }));
        // lattice mast
        const cs = 0.2;
        [-cs, cs].forEach((x) => [-cs, cs].forEach((z) => g.add(box(t, [0.06, H, 0.06], LATTICE, [x, H / 2, z], { tex: 'metal', metal: 0.5, rough: 0.4 }))));
        for (let y = 0.5; y < H; y += 0.4) {
          [-cs, cs].forEach((z) => g.add(box(t, [cs * 2, 0.04, 0.04], LATTICE, [0, y, z], { metal: 0.5, rough: 0.4 })));
          [-cs, cs].forEach((x) => g.add(box(t, [0.04, 0.04, cs * 2], LATTICE, [x, y, 0], { metal: 0.5, rough: 0.4 })));
        }
        g.add(ball(t, 0.14, ORANGE, [0, H + 0.1, 0], { rough: 0.5 }));

        const cabin = new t.Group();
        g.add(cabin);
        // blue drum with window band + floor and roof rings
        cabin.add(cyl(t, 0.95, 0.95, 0.55, BLUE, [0, 0.3, 0], { tex: 'plastic', repeat: [10, 1], rough: 0.45, seg: 28 }));
        cabin.add(cyl(t, 1.02, 1.02, 0.07, ORANGE, [0, 0.02, 0], { rough: 0.5, seg: 28 })); // floor ring
        for (let i = 0; i < 12; i++) {
          const a = (i / 12) * Math.PI * 2;
          const w = new t.Mesh(new t.BoxGeometry(0.02, 0.3, 0.2), new t.MeshStandardMaterial({ color: 0xbfe2f0, emissive: 0x2a4a66, emissiveIntensity: 0.35, roughness: 0.25 }));
          w.position.set(Math.cos(a) * 0.96, 0.32, Math.sin(a) * 0.96);
          w.rotation.y = -a;
          cabin.add(w);
        }
        // orange/white pinwheel cone roof
        const SEGS = 12;
        for (let i = 0; i < SEGS; i++) {
          const a0 = (i / SEGS) * Math.PI * 2;
          const wedge = new t.Mesh(new t.CylinderGeometry(0.03, 1.05, 0.42, 3, 1, false, a0, (Math.PI * 2) / SEGS), new t.MeshStandardMaterial({ color: i % 2 ? ORANGE : CREAM, roughness: 0.55 }));
          wedge.position.y = 0.78;
          wedge.castShadow = true;
          cabin.add(wedge);
        }
        cabin.add(ball(t, 0.07, ORANGE, [0, 1.02, 0], { rough: 0.5 }));
        // a few peeps visible at the windows
        for (let i = 0; i < 4; i++) {
          const a = (i / 4) * Math.PI * 2 + 0.4;
          const p = buildPeep(t, { skin: SKIN_TONES[i % SKIN_TONES.length], shirt: SHIRTS[i % SHIRTS.length] });
          p.group.scale.setScalar(0.32);
          p.group.position.set(Math.cos(a) * 0.62, 0.06, Math.sin(a) * 0.62);
          p.group.rotation.y = -a + Math.PI;
          cabin.add(p.group);
        }
        return (time) => {
          const cyc = (time * 0.18) % 1;
          const h = cyc < 0.5 ? cyc * 2 : (1 - cyc) * 2; // up then down
          cabin.position.y = 0.35 + h * (H - 1.5);
          cabin.rotation.y = time * 0.4;
        };
      }}
    />
  );
}

import React from 'react';
import { TwistRide } from './index';

const previews = {
  componentName: 'TwistRide',
  importPath: 'components/TwistRide',
  previews: [
    { name: '3D rig', description: "Twist: three arms with counter-rotating car clusters (TWIST1).", render: () => <TwistRide /> },
  ],
};

export default previews;

import React from 'react';
import * as THREE from 'three';
import { Stage, box, cyl } from '../Stage';
import { buildPeep, SHIRTS, SKIN_TONES } from '../Guest';

// Twist matched to the RCT2 TWIST1 sprite: a low central hub drives THREE
// maroon/orange arms, each ending in a spinning 2-car cluster — arms sweep one
// way while each cluster counter-rotates, giving the classic scissor motion.
export function TwistRide() {
  return (
    <Stage
      distance={6.5}
      targetY={0.7}
      build={(t, g) => {
        const RED = 0xb03428; // arms (sprite #a04030/#d04020)
        const MAROON = 0x7a1a3c; // hub + cluster plates (sprite #801040)
        g.add(cyl(t, 1.9, 2.0, 0.16, 0x8a8f98, [0, 0.08, 0], { tex: 'concrete', repeat: [12, 1], rough: 0.9, seg: 32 }));
        const hub = new t.Group();
        g.add(hub);
        hub.add(cyl(t, 0.35, 0.45, 0.5, MAROON, [0, 0.42, 0], { tex: 'metal', metal: 0.4, rough: 0.5, seg: 18 }));
        hub.add(cyl(t, 0.2, 0.2, 0.25, RED, [0, 0.8, 0], { metal: 0.4, rough: 0.5, seg: 14 }));
        const clusters: THREE.Group[] = [];
        for (let armI = 0; armI < 3; armI++) {
          const arm = new t.Group();
          arm.rotation.y = (armI / 3) * Math.PI * 2;
          hub.add(arm);
          arm.add(box(t, [1.5, 0.13, 0.22], RED, [0.75, 0.6, 0], { tex: 'metal', metal: 0.35, rough: 0.5 }));
          arm.add(box(t, [0.9, 0.09, 0.14], MAROON, [0.7, 0.48, 0], { metal: 0.35, rough: 0.5, rotZ: 0.12 }));
          const cluster = new t.Group();
          cluster.position.set(1.5, 0.52, 0);
          arm.add(cluster);
          cluster.add(cyl(t, 0.5, 0.5, 0.08, MAROON, [0, 0, 0], { metal: 0.3, rough: 0.55, seg: 18 })); // spin plate
          for (let ci = 0; ci < 2; ci++) {
            const ca = ci * Math.PI;
            const car = new t.Group();
            car.position.set(Math.cos(ca) * 0.45, 0.1, Math.sin(ca) * 0.45);
            car.rotation.y = -ca + Math.PI / 2;
            // tub car: rounded orange shell, open front, headrest
            car.add(cyl(t, 0.26, 0.3, 0.3, 0xd6541a, [0, 0.1, 0], { tex: 'plastic', repeat: [4, 1], rough: 0.4, seg: 16 }));
            car.add(box(t, [0.4, 0.24, 0.06], MAROON, [0, 0.2, -0.24], { rough: 0.5 }));
            const p = buildPeep(t, { skin: SKIN_TONES[(armI * 2 + ci) % SKIN_TONES.length], shirt: SHIRTS[(armI * 2 + ci) % SHIRTS.length], seated: true, expression: 'surprised' });
            p.group.scale.setScalar(0.36);
            p.group.position.set(0, -0.06, -0.03);
            car.add(p.group);
            cluster.add(car);
          }
          clusters.push(cluster);
        }
        return (time) => {
          hub.rotation.y = time * 1.1;
          clusters.forEach((c, i) => (c.rotation.y = -time * 2.6 + i));
        };
      }}
    />
  );
}

