import React from 'react';
import { Stage, box, cyl } from '../Stage';
import { buildPeep, SHIRTS, SKIN_TONES } from '../Guest';

// Enterprise matched to the RCT2 ENTERP sprite: a PINK-spoked wheel ringed
// with enclosed pod cars on a slate lattice support arm — the wheel spins up
// flat, then the arm lifts it toward vertical so the pods swing outward.
export function Enterprise() {
  return (
    <Stage
      distance={9}
      targetY={1.9}
      build={(t, g) => {
        const PINK = 0xd6338c;
        const SLATE = 0x3c5454;
        const POD = 0x2e4444;
        g.add(box(t, [1.6, 0.3, 2.4], 0x8a8f98, [-1.6, 0.15, 0], { tex: 'concrete', repeat: [5, 7], rough: 0.9 })); // machinery base
        const armPivot = new t.Group();
        armPivot.position.set(-1.6, 0.5, 0);
        g.add(armPivot);
        armPivot.add(box(t, [2.6, 0.22, 0.3], SLATE, [1.3, 0, 0], { tex: 'metal', metal: 0.5, rough: 0.45 })); // arm
        armPivot.add(box(t, [2.4, 0.14, 0.2], SLATE, [1.2, -0.22, 0], { metal: 0.5, rough: 0.45, rotZ: 0.08 }));
        const wheel = new t.Group();
        wheel.position.set(2.6, 0, 0);
        armPivot.add(wheel);
        const R = 1.5;
        // rim + 16 pink spokes
        const rim = new t.Mesh(new t.TorusGeometry(R, 0.06, 8, 40), new t.MeshStandardMaterial({ color: PINK, metalness: 0.3, roughness: 0.5 }));
        wheel.add(rim);
        for (let i = 0; i < 16; i++) wheel.add(box(t, [0.035, R * 2, 0.035], PINK, [0, 0, 0], { rotZ: (i / 16) * Math.PI, metal: 0.3, rough: 0.5 }));
        wheel.add(cyl(t, 0.14, 0.14, 0.2, SLATE, [0, 0, 0], { rotX: Math.PI / 2, metal: 0.6, rough: 0.4, seg: 16 }));
        // 10 enclosed pods hanging on the rim (mesh-front capsule cars)
        for (let i = 0; i < 10; i++) {
          const a = (i / 10) * Math.PI * 2;
          const pod = new t.Group();
          pod.position.set(Math.cos(a) * R, Math.sin(a) * R, 0.16);
          pod.rotation.z = a - Math.PI / 2; // hang outward along the rim
          wheel.add(pod);
          pod.add(cyl(t, 0.14, 0.18, 0.42, POD, [0, -0.1, 0], { tex: 'metal', metal: 0.3, rough: 0.55, seg: 12 }));
          pod.add(box(t, [0.2, 0.3, 0.02], 0x9fb6c0, [0, -0.08, 0.1], { metal: 0.4, rough: 0.3, opacity: 0.75 })); // mesh front
          const p = buildPeep(t, { skin: SKIN_TONES[i % SKIN_TONES.length], shirt: SHIRTS[i % SHIRTS.length], seated: true });
          p.group.scale.setScalar(0.26);
          p.group.position.set(0, -0.26, 0.02);
          pod.add(p.group);
        }
        return (time) => {
          wheel.rotation.z = time * 1.6;
          const lift = (Math.sin(time * 0.35) + 1) / 2; // 0..1
          armPivot.rotation.z = lift * 1.15; // raise toward vertical
        };
      }}
    />
  );
}
